import{_ as e,H as a,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const _=JSON.parse('{"title":"结束语 | 在技术的浪潮中，成为奔腾不息的后浪","description":"","frontmatter":{},"headers":[{"level":2,"title":"成长关键词一：坚持","slug":"成长关键词一-坚持","link":"#成长关键词一-坚持","children":[]},{"level":2,"title":"成长关键词二：突破","slug":"成长关键词二-突破","link":"#成长关键词二-突破","children":[]},{"level":2,"title":"Python 学习的长远规划","slug":"python-学习的长远规划","link":"#python-学习的长远规划","children":[]}],"relativePath":"Python实战·从0到1搭建直播视频平台/结束语｜在技术的浪潮中，成为奔腾不息的后浪.md","filePath":"Python实战·从0到1搭建直播视频平台/结束语｜在技术的浪潮中，成为奔腾不息的后浪.md","lastUpdated":1795533265000}'),o={name:"Python实战·从0到1搭建直播视频平台/结束语｜在技术的浪潮中，成为奔腾不息的后浪.md"};function i(E,t,r,h,s,B){return a(),n("div",null,[...t[0]||(t[0]=[p('<h1 id="结束语-在技术的浪潮中-成为奔腾不息的后浪" tabindex="-1">结束语 | 在技术的浪潮中，成为奔腾不息的后浪 <a class="header-anchor" href="#结束语-在技术的浪潮中-成为奔腾不息的后浪" aria-label="Permalink to &quot;结束语 | 在技术的浪潮中，成为奔腾不息的后浪&quot;">​</a></h1><p>你好，我是 Barry。</p><p>时间转瞬即逝，我们不知不觉一起完成了整个课程的学习，步入了专栏的尾声。</p><p>从整个课程规划到产出落地历经大半年，我在回复很多同学评论区的问题时，常常会说“我们一起加油”。起初我还担心，这么说会不会让人觉得这个老师太假了，什么都让我们“加油”，但其实这是我发自肺腑想说的话。</p><p>既然你选择了学习 Python 全栈，就希望你加油坚持下去。既然我开了这门课程，就会加油把它做好。课程的最后，我想和你说说我的一些心里话。</p><h2 id="成长关键词一-坚持" tabindex="-1">成长关键词一：坚持 <a class="header-anchor" href="#成长关键词一-坚持" aria-label="Permalink to &quot;成长关键词一：坚持&quot;">​</a></h2><p>第一个想说的关键词就是“坚持”。这世上大部分的事情，都不是今天努力明天就能看到结果。坚持不是三分钟的热度，而是需要长时间的积累，需要付出，需要有始有终。</p><p>就拿这个专栏来说，从主题策划到完结一共经历了大半年的时间。我的体会就是痛并快乐着，因为本身工作也很忙，只能利用好一切业余时间来产出内容。但每当看到评论区里的提问、反馈，我又总是很振奋，你们的支持也是我坚持不懈的动力。</p><p>长时间坚持写作是对身体和心理的双重考验，甚至让我想起了自己刚参加工作前的时光。在大四上半学期的校招中，我有幸以同批校招最高的薪资被一家国企选中，去做技术研发。当时最终的面试是 12 选 1，竞争相当激烈。被选中的那一刻我立马给我母亲打通电话，甚至喜极而泣，也是巨大压力的情绪爆发。</p><p>幸运的背后，是我那段时间放弃了所有无用活动，每天泡在实验室敲代码，我记不得自己在那段时间练了多少项目，写了多少遍增删改查，解决掉了多少的 BUG。这个过程是和“自己斗”的过程。我坚信大量的项目实践一定能让我更深入地掌握和理解技术，而这样的坚持也让我尝到了“甜头”。</p><h2 id="成长关键词二-突破" tabindex="-1">成长关键词二：突破 <a class="header-anchor" href="#成长关键词二-突破" aria-label="Permalink to &quot;成长关键词二：突破&quot;">​</a></h2><p>我觉得自己的技术成长速度还是相对比较快的，切换得也比较快。虽然过程中也是挑战重重，但抱着突破自己的心态，我一直没有退却。</p><p>参加工作后，我发现我比别人“慢”了。慢在我觉得我没有“灵性”，问题出在我那会儿沉迷于“做出来就行”，并没深入理解原理。</p><p>比如我在刚开始用 Vue 框架的时候，一再追求怎么样能写出来一个功能，但是我连 Vue 的生命周期都搞不懂。结果很容易猜到，一味求快，不修内功，自然寸步难行。</p><p>于是，我开始调整自己的学习方式，克服畏难情绪，去啃原理。这么做果然效率极高，当然这个过程依然离不开大量的实践。我为了锻炼自己，开始申请独立来完成项目，功夫不负有心人，因此我整个职业晋升路线也上升比较快。我从原理学习这件事儿尝到了甜头，所以也希望你在技术成长路上养成好习惯。我们总说“面试造航母”，仅仅从技术招聘的角度出发，你也必须具备足够扎实的基础。</p><p>坚持和突破是两个相辅相成的成长“密码”。只有坚持，你才能建立完备的知识体系，只有突破，你才能不断拓宽技术栈，敢于去拥抱变化、尝试新东西。</p><h2 id="python-学习的长远规划" tabindex="-1">Python 学习的长远规划 <a class="header-anchor" href="#python-学习的长远规划" aria-label="Permalink to &quot;Python 学习的长远规划&quot;">​</a></h2><p>大部分的成长之路需要自己独行。在临别之际，我还想和你聊一下 Python 技术学习的长远规划。</p><p>很多同学可能存在的一些困惑，就是学习全栈之后，下一步该做哪些拓展，怎样去持续提升。</p><p>结合现状市面的岗位需求，我梳理了一张横向和纵向发展的思维导图，你可以看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>纵向发展更聚焦提升技术深度和应用能力，我最看好的是数据分析、大数据、微服务这三个方向。</p><p>数据分析的应用场景非常多，像电子商务、金融行业、医疗行业、能源行业、交通运输行业等都需要。本身具备了 Python 的开发能力，也有了 NumPy 和 Pandas 基础之后，更有利于往这个领域迈进。</p><p>当然。你需要继续花一些时间精力在机器学习和算法基础巩固上。机器学习的基础知识包括分类、回归、聚类等等。为了更好地理解和优化数据分析算法，比如排序、搜索、图算法、复杂性分析的相关知识也必不可少。</p><p>大数据应用就更广了。具备了大数据相关的能力，你就可以去处理解决更复杂、更大体量的项目。就拿直播平台来说，你可以通过大数据来实现对直播平台用户的行为分析，从而定制私有化推荐，让平台的能力更上一层楼。</p><p>想要在大数据应用方向深耕，你不但需要了解分布式计算框架，如 Hadoop、Spark、Flink等，还需要学会使用 Python 与这些框架进行交互，处理大规模的数据集。</p><p>微服务的应用也比较普遍，也是一个后端工程师必备的技能。微服务可以帮我们将应用程序分解为更小的、独立的服务，每个服务都可以独立地开发和部署，更灵活地满足应用程序的需求。同时，微服务允许我们将对每个服务的依赖最小化，降低应用程序的整体风险，这也是企业级项目开发中必不可少的应用。</p><p>对于横向维度，结合行业发展趋势来看，我建议你熟悉了 Python 应用之后，尝试向人工智能方向里的推荐系统、算法、大模型都是可以考虑的方向。</p><p>推荐系统是人工智能目前落地非常不错的应用，各类电商、短视频、餐饮、旅行、团购平台都需要具备推荐能力，它们都是人工智能的具象产物。</p><p>想要往这方面发展，你需要深耕人工智能算法相关知识。机器学习算法、深度学习相关知识都必不可少。使用最广泛的深度学习框架 TensorFlow、PyTorch，都提供了 Python API，让我们能使用 Python 编写深度学习模型。</p><p>你也可以尝试去追逐一下技术风口，比如人工智能里的大模型方向，各大企业都在争相布局，开发自己的独立大模型。另外，还有因技术变革涌现的新岗位，比如提示工程师、模型训练师，你都可以去多多了解。</p><p>总之，我期望你的选择一定是在慎重考虑之后的决定，选择合适自己的才是最好的。</p><p>好，再次感谢你的一路陪伴。我是 Barry，让我们努力成为奔腾不息的后浪，坚定不移，勇往直前，加油！</p><p>最后，希望你可以花几分钟填一下结课问卷，非常期待听到你的声音。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Python%E5%AE%9E%E6%88%98%C2%B7%E4%BB%8E0%E5%88%B01%E6%90%AD%E5%BB%BA%E7%9B%B4%E6%92%AD%E8%A7%86%E9%A2%91%E5%B9%B3%E5%8F%B0/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p>',35)])])}const c=e(o,[["render",i]]);export{_ as __pageData,c as default};
